 :focus-visible { outline: 3px solid #bf7c00; outline-offset: 3px; }
 #projects { margin-top: 28px; }
-.project-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 16px; margin-bottom: 12px; background: white; border: 1px solid #d8dfea; border-radius: 8px; }
+.project-row { flex-wrap: wrap; display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 16px; margin-bottom: 12px; background: white; border: 1px solid #d8dfea; border-radius: 8px; }
 .project-row span { overflow-wrap: anywhere; min-width: 0; }
 .project-row button { flex-shrink: 0; }
+#create-project { margin-bottom: 24px; }
 #create-task { margin: 24px 0; }
 select { padding: 10px; font: inherit; border: 1px solid #7d8a9c; border-radius: 6px; }
 #tasks { margin-top: 20px; }
 .task-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 16px; margin-bottom: 12px; background: white; border: 1px solid #d8dfea; border-radius: 8px; }

